/**
 * Shape of catalog.manifest.json (generated by `kit:manifest`). Self-contained on purpose: apps can
 * read the JSON with these types without importing anything else from the kit.
 */

export type CatalogTier = 'basic' | 'pro';

export interface CatalogVariant {
  /** `<slot>/<variant>`, the value pair of data-lz-slot / data-lz-variant. */
  key: string;
  slot: string;
  variant: string;
  label: string;
  region: 'header' | 'main' | 'footer';
  description: string;
  intent: string | null;
  /** legacy: a spec without brand.catalog may pick it; extended: newer folders. */
  catalog: 'legacy' | 'extended';
  /** Tiers it is designed for: meta.tiers, or the blueprints when the meta doesn't say. */
  tiers: CatalogTier[];
  /** Tiers whose blueprint lets the spec compiler place it today. */
  blueprintTiers: CatalogTier[];
  /** Declared for Pro only and the Básico blueprint doesn't allow it. A variant with no declared tier (tiers: []) is never Pro-only. */
  proOnly: boolean;
  /** Blueprint roles that resolve to this slot. */
  roles: string[];
  contentKeys: string[];
  /** Literal id="…" anchors in the fragment. */
  anchors: string[];
  /** The fragment carries data-lz-fit (viewport-fit system). */
  fit: boolean;
  numbered: boolean;
  archetypes: string[];
  family: string | null;
  /** Lattiz Motion type and default pattern the seed assigns to this slot (Pro only); null = none. */
  motion: { type: string; pattern: string | null } | null;
  /** Motion runtime hooks written in the fragment itself (data-lz-counter, …). */
  hooks: string[];
}

export interface CatalogHook {
  attribute: string;
  /** The runtime that reads it is injected only for Pro tenants (tenant-sites compose-site). */
  proOnly: boolean;
}

export interface CatalogPalette {
  id: string;
  label: string;
  scheme: 'light' | 'dark';
  /** Library palettes: light | dark | tinted; giro palettes: null. */
  mode: string | null;
  mood: string[];
  affinity: string[];
  /** Accent hue in degrees, or null for a near-gray accent (not counted by the 30° rule). */
  accentHue: number | null;
}

export interface CatalogFontPair {
  id: string;
  label: string;
  catalog: 'legacy' | 'extended';
  mood: string[];
  affinity: string[];
}

export interface CatalogArchetype {
  id: string;
  label: string;
  intent: string;
  dials: { variance: number; motion: number; density: number };
  motion: string;
  moods: string[];
  giros: string[];
  sections: Record<CatalogTier, { role: string; variants: string[] }[]>;
}

export interface CatalogGiro {
  id: string;
  label: string;
  /** Legacy palette ids (giros/<id>.ts), in pick order. */
  palettes: string[];
  fontPairs: string[];
}

export interface CatalogPrimitiveStyle {
  id: string;
  intent: string;
  /** Written explicitly in markup for a context; never a theme-wide choice. */
  contextual: boolean;
  /** CSS cost when a template uses it (raw / gzip level 9, bytes). */
  bytes: { raw: number; gzip: number };
}

export interface CatalogPrimitive {
  family: string;
  label: string;
  /** BEM block (`lz-btn`); a style is `<block>--<style>`. */
  block: string;
  defaultStyle: string | null;
  roles: string[];
  /** base.css, emitted once when any element of the family is used. */
  base: { raw: number; gzip: number };
  styles: CatalogPrimitiveStyle[];
}

export interface CatalogDirection {
  id: string;
  name: string;
  intent: string;
  palettes: { default: string[]; byGiro: Record<string, string[]> };
  fontPairs: { default: string[]; byGiro: Record<string, string[]> };
  style: Record<string, string>;
  primitives: Record<string, string>;
  archetypes: string[];
  heroes: Record<CatalogTier, string[]>;
  motion: string;
  dials: { variance: number; motion: number; density: number };
  giros: string[];
  rules: string[];
  voice: { register: string; headline: string; cta: string };
}

export interface CatalogManifest {
  $comment: string;
  manifestVersion: 1;
  /** sha256 (16 hex) of the canonical manifest without this field. */
  contentHash: string;
  /** src/spec/catalog.ts CATALOG_VERSION. */
  catalogVersion: number;
  variants: CatalogVariant[];
  primitives: CatalogPrimitive[];
  directions: CatalogDirection[];
  hooks: CatalogHook[];
  archetypes: CatalogArchetype[];
  palettes: {
    extended: CatalogPalette[];
    giros: Record<string, CatalogPalette[]>;
  };
  fontPairs: CatalogFontPair[];
  giros: CatalogGiro[];
}
